NEW_FILES = {'test_office_floor_kind.py': '"""An office building\'s open floor is an office, not a shop floor (0.248.0, the factory\'s roadmap 281).\n\n`floor` is a shop-floor word, so the office preset\'s 816 m2 `floor_1` -- office\'s and office_stepped\'s open storey over\nthe bullpen -- was furnished with a service counter, vending machines, shelf runs and litter bins; cold run 9369\'s frame\nof it showed the bins standing mid-floor among cartons. `level_design.is_office_floor` reads it on the card shop\'s\nterms: a building whose id says `office`, a room the word table would make a shop floor by `floor` alone.\n"""\nimport collections\nimport json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport level_design as L  # noqa: E402\n\nHERE = os.path.dirname(os.path.abspath(__file__))\n#: The library\'s other rooms that are shop floors by `floor` alone, when 0.248.0 was written: a warehouse\'s, a depot\'s,\n#: a foundry\'s, a brewery\'s, an arena\'s and a supermarket\'s mezzanine. They keep their kind.\nOTHER_BARE_FLOORS = (\n    ("arena_a01", "event_floor"), ("arena_a02", "event_floor"), ("arena_a03", "event_floor"),\n    ("brewery_a01", "brew_floor"), ("depot_a02", "floor"), ("foundry_heist_vertical", "central_floor"),\n    ("foundry_heist_vertical", "east_floor"), ("freight_terminal_a02", "south_floor"),\n    ("large_warehouse_a02", "south_floor"), ("large_warehouse_a03", "main_floor"), ("setback_demo", "main_floor"),\n    ("supermarket_a02", "mezz_floor"), ("warehouse_a02", "main_floor"),\n)\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef test_an_office_building_s_floor_is_an_office():\n    for b in ("office", "office_stepped", "lf_tower_007_3 office"):\n        for rid in ("floor_1", "floor_2"):\n            # the kind first, so 0.247.0 fails on the kind and not on a missing name\n            assert L._room_kind({"id": rid, "story": 1}, b) == "office", (b, rid)\n            assert L.is_office_floor({"id": rid}, b), (b, rid)\n\n\ndef test_every_other_bare_floor_keeps_its_kind():\n    for b, rid in OTHER_BARE_FLOORS:\n        assert L._room_kind({"id": rid, "story": 0}, b) == "shop_floor", (b, rid)\n        assert not L.is_office_floor({"id": rid}, b), (b, rid)\n\n\ndef test_the_rule_asks_the_word_floor_alone():\n    """A room that names a stronger kind keeps it, and `floor` beside a real shop word is a shop floor still; a\n    building whose words only contain `office` is not one."""\n    assert L._room_kind({"id": "ground_bullpen"}, "office") == "office"\n    assert L._room_kind({"id": "lobby"}, "office") == "lobby"\n    assert L._room_kind({"id": "sales_floor"}, "office") == "shop_floor"\n    assert not L.is_office_floor({"id": "sales_floor"}, "office")\n    assert not L.is_office_floor({"id": "floor_1"}, "post_officer")\n    assert not L.is_office_floor({"id": "floor_1"}, None)\n\n\ndef test_the_library_office_floors_hold_desks_and_no_shop_stock():\n    for name in ("office", "office_stepped"):\n        d = _spec(name)\n        (room,) = [r for r in d["rooms"] if r["id"] == "floor_1"]\n        tag = "_%s_" % L._room_tag(room)\n        stems = collections.Counter(v["name"].split("_" + L._room_tag(room))[0] for v in d["volumes"]\n                                    if tag in v.get("name", ""))\n        assert stems["desk"] >= 4, (name, dict(stems))\n        assert not stems.keys() & {"litter_bin", "vending", "counter_service", "atm_store", "poster_wall_store"}, \\\n            (name, dict(stems))\n'}
CHANGELOG = '## [0.248.0] - an office building\'s open floor is an office\n\n**The factory\'s roadmap 281.** `floor` is a shop-floor word in `_ROOM_KINDS` -- "a shop floor is shelving and stock"\n-- so the office preset\'s open storey over the bullpen, `floor_1` (816 m2 in office and office_stepped), was furnished\nby the shop floor\'s recipe. 0.246.0\'s count fix let it reach its target, and cold run 9369\'s frame of office\'s showed\nlitter bins standing mid-floor among carton stacks.\n\n### Added\n- **`is_office_floor(room, building)`**, read in `_room_kind` after the strip club\'s, the card shop\'s and the video\n  store\'s rules and on their terms: a building whose id says `office`, and a room the word table would make a shop\n  floor by the word `floor` alone. A room that names a stronger kind keeps it (`ground_bullpen` is an office,\n  `lobby` a lobby), and `floor` beside a real shop word is a shop floor still.\n\n### Changed\n- **The library refurnished**: office\'s `floor_1` goes from a service counter, three vending machines, two filing\n  cabinets, four shelf runs, four cartons and four litter bins to four desks and their chairs, three shelf runs, six\n  filing cabinets and five cartons; office_stepped\'s from five litter bins and nine cartons to six desks and their\n  chairs and ten cartons. No other room in the library moves. The library\'s other thirteen rooms that are shop floors\n  by `floor` alone -- an arena\'s event floors, a brewery\'s, a depot\'s, a foundry\'s, a freight terminal\'s and the\n  warehouses\' floors, a supermarket\'s mezzanine -- keep their kind; each is a question of its own.\n\n### Tests\n- **test_office_floor_kind.py** (new, 4): an office building\'s floor_N is an office; the other thirteen bare floors\n  keep their kind; the rule asks `floor` alone; the library\'s two office floors hold desks and no shop stock. On\n  0.247.0 two fail on behaviour -- `floor_1` reads `shop_floor`, and the library\'s office floors hold litter bins and\n  no desk -- and two are guards whose kind halves hold there, failing only on the new function\'s name.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.247.0', 'Deli Counter 0.248.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
